let ytItems = [];
try {
  const ytResp = $input.first().json;
  for (const v of (ytResp.items || [])) {
    const sn = v.snippet || {};
    if (sn.title) ytItems.push({ topic: sn.title.trim(), source: 'youtube_trending', tags: sn.tags || [] });
  }
} catch(e) { console.log('YouTube parse failed:', e.message); }

let trendsItems = [];
try {
  const r = await $http.get('https://trends.google.com/trends/trendingsearches/daily/rss?geo=IN');
  const xml = typeof r.data === 'string' ? r.data : JSON.stringify(r.data);
  const matches = [...xml.matchAll(/<title>(?:<!\[CDATA\[)?([^<\]]+?)(?:\]\]>)?<\/title>/g)];
  for (const m of matches.slice(1)) {
    const t = m[1].trim();
    if (t) trendsItems.push({ topic: t, source: 'google_trends_daily', tags: [] });
  }
} catch(e) { console.log('Trends RSS failed:', e.message); }

let newsItems = [];
try {
  const r = await $http.get('https://news.google.com/rss?hl=en-IN&gl=IN&ceid=IN:en');
  const xml = typeof r.data === 'string' ? r.data : JSON.stringify(r.data);
  const matches = [...xml.matchAll(/<title>(?:<!\[CDATA\[)?([^<\]]+?)(?:\]\]>)?<\/title>/g)];
  for (const m of matches.slice(1, 101)) {
    const t = m[1].trim();
    if (t) newsItems.push({ topic: t, source: 'google_news_rss', tags: [] });
  }
} catch(e) { console.log('News RSS failed:', e.message); }

const T1 = ['buy','price','cheap','best','review','order','shop','deal','discount','sale','offer','coupon','promo code','clearance','cash on delivery','cod','free shipping','emi','in stock','where to buy','lowest price','cheap price','wholesale','bulk','dropship','distributor','under 500','under 1000'];
const T2 = ['alternative to','similar to','replacement for','specs','specifications','features','dimensions','unboxing','hands on','teardown','pros and cons','is it worth it','buying guide','top 10','top 5','tier list','ranking','benchmarks','reddit','quora','combo','kit','pack','vs','comparison'];
const T3 = ['wireless','portable','new','latest','trending','india 2026','original','authentic','genuine','fake vs real','refurbished','second hand','used','open box','warranty','return policy','customer service','size chart','colors','variants','edition','flash sale','limited time','lightning deal','restock','sold out','in stock tracker','pre-order','launch date','release date','early access','near me'];
const NEG = ['how to','tutorial','diy','repair','fix','not working','error','broken','manual','pdf','driver download','free download'];
const CAT = {
  electronics: ['wireless','bluetooth','earbuds','phone','laptop','usb','charger','led','power bank','smartwatch','speaker','monitor','cable','adapter','tablet','camera'],
  fashion: ['shirt','dress','kurta','saree','sneakers','watch','bag','sunglasses','jeans','t-shirt','jacket','shoes','hoodie','heels','wallet','belt'],
  home: ['kitchen','decor','organizer','cleaning','storage','fan','cooler','light','bottle','bedsheet','pillow','cookware','blender','mop','towel','vacuum'],
  fitness: ['gym','yoga','protein','supplement','band','tracker','cycle','dumbbells','mat','creatine','whey','treadmill','resistance','shaker','massager'],
  beauty: ['skincare','hair','serum','moisturizer','lipstick','foundation','sunscreen','shampoo','perfume','lotion','concealer','trimmer','face wash','makeup','cleanser'],
  accessories: ['case','cover','stand','holder','mount','strap','tempered glass','sleeve','skin','guard','ring','tripod','grip','hub'],
  automotive: ['car','bike','helmet','dashcam','tyre','wax','polish','wiper','gps','inflator','mat','coolant','scratch','jump starter','perfume'],
  baby_and_kids: ['toy','puzzle','lego','diaper','stroller','wipes','pacifier','onesie','rattle','plush','scooter','doll','action figure','bottle'],
  pets: ['dog','cat','food','collar','leash','bed','litter','treats','aquarium','grooming','cage','harness','shampoo','bowl'],
  office_and_stationery: ['book','notebook','pen','desk','chair','printer','paper','marker','folder','diary','planner','stapler','calculator','ink'],
  health_and_medical: ['thermometer','massager','vitamins','mask','sanitizer','first aid','scale','oximeter','braces','monitor','inhaler','test kit','support'],
  tools_and_hardware: ['drill','screwdriver','wrench','saw','tape','hammer','screws','pliers','multimeter','ladder','glue','toolkit','nails','hinge'],
  grocery_and_food: ['coffee','tea','snacks','chocolate','dry fruits','oil','rice','spices','honey','noodles','sauce','cereal','pasta','biscuit']
};
const STOP = new Set(['a','an','the','in','of','for','with','is','are','was','were','and','or','on','at','to','by','from']);

function scoreIntent(topic, related) {
  const h = [topic, ...related].join(' ').toLowerCase();
  let s = 0;
  T1.forEach(p => { if (h.includes(p)) s += 0.30; });
  T2.forEach(p => { if (h.includes(p)) s += 0.15; });
  T3.forEach(p => { if (h.includes(p)) s += 0.10; });
  NEG.forEach(p => { if (h.includes(p)) s -= 0.20; });
  return Math.round(Math.max(0, Math.min(1, s)) * 1000) / 1000;
}

function mapCats(topic, related) {
  const h = [topic, ...related].join(' ').toLowerCase();
  const m = [];
  for (const [c, kws] of Object.entries(CAT)) {
    for (const kw of kws) {
      if (new RegExp('\\b' + kw.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + '\\b').test(h)) { m.push(c); break; }
    }
  }
  return m.length ? m : ['uncategorized'];
}

function normWords(t) {
  return new Set(t.toLowerCase().replace(/[^\w\s]/g,' ').split(/\s+/).filter(w => w && !STOP.has(w)));
}

function dedupe(items) {
  const kept = [];
  for (const c of items) {
    const cw = normWords(c.topic);
    if (!cw.size) continue;
    let di = -1;
    for (let i = 0; i < kept.length; i++) {
      const ew = normWords(kept[i].topic);
      const ov = [...cw].filter(w => ew.has(w)).length;
      const smaller = Math.min(cw.size, ew.size);
      if (smaller && ov / smaller > 0.70) { di = i; break; }
    }
    if (di === -1) kept.push(c);
    else if ((c.related_queries||[]).length > (kept[di].related_queries||[]).length) kept[di] = c;
  }
  return kept;
}

const raw = [...ytItems, ...trendsItems, ...newsItems].slice(0, 1000);
const enriched = raw.map(item => {
  const related = item.tags.slice(0, 10);
  return {
    topic: item.topic,
    traffic_estimate: 'N/A',
    source: item.source,
    related_queries: related,
    product_intent_score: scoreIntent(item.topic, related),
    suggested_categories: mapCats(item.topic, related)
  };
});
const deduped = dedupe(enriched);
deduped.sort((a, b) => b.product_intent_score - a.product_intent_score);
const ranked = deduped.map((t, i) => ({ rank: i + 1, ...t }));

const payload = {
  metadata: {
    scraped_at: new Date().toISOString(),
    geo: 'IN',
    total_topics: ranked.length,
    sources: ['google_trends_daily', 'youtube_trending', 'google_news_rss']
  },
  trends: ranked
};

console.log(`Done: ${ranked.length} topics | YT:${ytItems.length} Trends:${trendsItems.length} News:${newsItems.length}`);
return [{ json: payload }];

const payload = $('Fetch . Score . Dedupe . Rank').first().json;
const runDate = payload.metadata?.scraped_at?.substring(0, 10) ?? new Date().toISOString().substring(0, 10);

return payload.trends.map(t => ({ json: {
  run_date: runDate,
  rank: t.rank,
  topic: t.topic,
  source: t.source,
  traffic_estimate: t.traffic_estimate ?? 'N/A',
  product_intent_score: t.product_intent_score,
  related_queries: (t.related_queries || []).join(', '),
  suggested_categories: (t.suggested_categories || []).join(', ')
}}));

const payload = $('Fetch . Score . Dedupe . Rank').first().json;
const date = new Date().toISOString().substring(0, 10);
const filename = `trending_india_${date}.json`;
const content = JSON.stringify(payload, null, 2);
const base64 = Buffer.from(content, 'utf-8').toString('base64');
return [{
  json: { filename },
  binary: {
    data: {
      data: base64,
      mimeType: 'application/json',
      fileName: filename,
      fileExtension: 'json'
    }
  }
}];

const payload = $input.first().json;
const top30 = payload.trends.slice(0, 30);
const run_date = payload.metadata?.scraped_at?.substring(0, 10) ?? new Date().toISOString().substring(0, 10);
const topics_text = top30.map(t =>
  `${t.rank}. "${t.topic}" | intent:${t.product_intent_score} | cats:${(t.suggested_categories||[]).join(',')} | src:${t.source}`
).join('\n');
return [{ json: { topics_text, run_date, total: top30.length } }];

const inp = $input.first().json;
const query = String(inp.query ?? inp.input ?? inp.text ?? '');
if (!query) return 'No query provided';

const res = await fetch('https://api.tavily.com/search', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    api_key: 'REDACTED_TAVILY_KEY',
    query: query,
    max_results: 5,
    include_answer: true,
    search_depth: 'basic'
  })
});
const d = await res.json();
const answer = d.answer || '';
const results = (d.results || []).slice(0, 5)
  .map(r => `- ${r.title}: ${(r.snippet || r.content || '').substring(0, 200)}`)
  .join('\n');
return answer ? `${answer}\n\nSources:\n${results}` : results || 'No results found';

const output = $input.first().json.output ?? '';
const run_date = $('Filter Top 30').first().json.run_date;
let picks = [];
try {
  const match = output.match(/\[[\s\S]*\]/);
  if (match) picks = JSON.parse(match[0]);
} catch(e) { console.log('JSON parse error:', e.message); }
return picks.length
  ? picks.map(p => ({ json: { run_date, ...p } }))
  : [{ json: { run_date, error: 'No picks parsed', raw: output.substring(0, 500) } }];

// Convert a curated AI pick into a CJ keyword search.
// Phase 2 v2: prefer the new `search_query_in` field (sharper India-market query)
// before falling back to the old parenthetical-extraction heuristic.
const FILLER = /\b(merchandise|themed|product|products|specific|official|fan[- ]?made|gaming|movie|music|artist|web|series|character|celebrity|focused|collectible|collectibles|accessories|apparel|cultural|items|memorabilia|regional|song|songs|romantic|symbol|symbols|new|latest)\b/g;
const items = $input.all();
const out = [];
for (const it of items) {
  const j = it.json || {};
  if (j.error) continue;

  // 1. Prefer the new search_query_in field if present
  let cleaned = '';
  if (j.search_query_in && String(j.search_query_in).trim()) {
    cleaned = String(j.search_query_in).toLowerCase()
      .replace(/[^a-z0-9\s\-]+/g, ' ')
      .replace(/\s+/g, ' ').trim()
      .split(' ').filter(w => w.length > 1).slice(0, 6).join(' ');
  }
  // 2. Fallback to legacy heuristic on suggested_product_type / topic
  if (!cleaned) {
    let raw = String(j.suggested_product_type || j.topic || '');
    const paren = raw.match(/\(([^)]+)\)/);
    if (paren) raw = paren[1];
    cleaned = raw.toLowerCase()
      .replace(/[^a-z0-9\s\-,]+/g, ' ')
      .replace(/[,\-]+/g, ' ')
      .replace(/\s+/g, ' ')
      .replace(FILLER, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    cleaned = cleaned.split(' ').filter(w => w.length > 2).slice(0, 3).join(' ');
  }
  if (!cleaned) {
    cleaned = String(j.topic || '').toLowerCase()
      .replace(/[^a-z0-9\s]+/g, ' ').replace(/\s+/g, ' ').trim()
      .split(' ').slice(0, 3).join(' ');
  }
  if (!cleaned) continue;

  out.push({ json: {
    keyword: cleaned,
    source_topic: j.topic || cleaned,
    source_pick_rank: j.rank ?? null,
    opportunity_score: j.opportunity_score ?? null,
    run_date: j.run_date || new Date().toISOString().substring(0,10),
  }});
}
return out;

// Filter CJ list, sort by listedNum, keep top 3 best matches.
// Input: each item has .json.data.list[] from CJ API + passthrough metadata via $('Build Search Query')
const items = $input.all();
const out = [];

function parsePrice(s) {
  if (!s) return null;
  const nums = String(s).match(/[\d.]+/g);
  if (!nums || !nums.length) return null;
  // CJ returns ranges like "2.02 -- 14.10"; take the lower bound
  return parseFloat(nums[0]);
}

for (let i = 0; i < items.length; i++) {
  const it = items[i].json || {};
  const meta = $('Build Search Query').all()[i]?.json || {};
  const list = it?.data?.list || [];
  const kwTokens = String(meta.keyword || '').split(/\s+/).filter(w => w.length > 2);

  // Prefer items whose English name shares at least 1 token with the keyword,
  // but if the strict filter yields fewer than 3 we top up with the rest of the list.
  const strict = list.filter(p => {
    const name = String(p.productNameEn || p.productName || '').toLowerCase();
    return kwTokens.some(t => name.includes(t));
  });
  strict.sort((a,b) => (b.listedNum||0) - (a.listedNum||0));
  let top = strict.slice(0, 3);
  if (top.length < 3) {
    const seen = new Set(top.map(p => p.pid));
    const rest = list.filter(p => !seen.has(p.pid)).sort((a,b) => (b.listedNum||0) - (a.listedNum||0));
    top = top.concat(rest.slice(0, 3 - top.length));
  }

  for (const p of top) {
    const imgs = String(p.productImage || '').split(';').filter(Boolean);
    out.push({ json: {
      run_date: meta.run_date,
      source_topic: meta.source_topic,
      source_pick_rank: meta.source_pick_rank,
      opportunity_score: meta.opportunity_score,
      source_provider: 'cj_dropshipping',
      product_name: p.productNameEn || p.productName || null,
      product_url: `https://app.cjdropshipping.com/product/${p.pid}.html`,
      product_sku: p.productSku || null,
      price_text: String(p.sellPrice || ''),
      price_numeric: parsePrice(p.sellPrice),
      currency: 'USD',
      description: '',
      image_urls: JSON.stringify(imgs),
      offers: JSON.stringify([{
        listedNum: p.listedNum || 0,
        supplierName: p.supplierName || null,
        isFreeShipping: !!p.isFreeShipping,
        shippingCountryCodes: p.shippingCountryCodes || null,
        categoryName: p.categoryName || null,
      }]),
      raw_payload: JSON.stringify(p),
      scraped_at: new Date().toISOString(),
    }});
  }
}
return out;

// Reformat Pick Top 3 items into flat human-readable rows for Google Sheets.
// JSON-stringified fields (image_urls, offers, raw_payload) are unpacked and joined.
const items = $('Pick Top 3').all();
const out = [];
for (const it of items) {
  const j = it.json || {};
  let imgs = [];
  let offers = [];
  try { imgs = JSON.parse(j.image_urls || '[]'); } catch(e) {}
  try { offers = JSON.parse(j.offers || '[]'); } catch(e) {}
  const offer = offers[0] || {};
  out.push({ json: {
    run_date: j.run_date,
    source_pick_rank: j.source_pick_rank,
    opportunity_score: j.opportunity_score,
    source_topic: j.source_topic,
    source_provider: j.source_provider,
    product_name: j.product_name,
    product_url: j.product_url,
    product_sku: j.product_sku,
    price_text: j.price_text,
    price_numeric: j.price_numeric,
    currency: j.currency,
    image_urls: imgs.join(', '),
    image_count: imgs.length,
    listed_num: offer.listedNum ?? '',
    supplier: offer.supplierName ?? '',
    free_shipping: offer.isFreeShipping ? 'YES' : 'no',
    shipping_countries: offer.shippingCountryCodes ?? '',
    category: offer.categoryName ?? '',
    scraped_at: j.scraped_at,
  }});
}
return out;

// Aggregate all scraped products into a single JSON file (binary attachment).
const all = $input.all().map(i => i.json);
const run_date = all[0]?.run_date || new Date().toISOString().substring(0,10);
const payload = {
  metadata: {
    run_date,
    total_products: all.length,
    scraped_at: new Date().toISOString(),
    source_providers: [...new Set(all.map(p => p.source_provider).filter(Boolean))],
  },
  products: all,
};
const filename = `scraped_products_${run_date}.json`;
const content = JSON.stringify(payload, null, 2);
const base64 = Buffer.from(content, 'utf-8').toString('base64');
return [{
  json: { filename, total: all.length },
  binary: { data: { data: base64, mimeType: 'application/json', fileName: filename, fileExtension: 'json' } }
}];

const inp = $input.first().json;
const err = inp.error || inp;
const nodeName = err?.node?.name || err?.context?.nodeName || 'Unknown Node';
const msg = (err?.message || err?.description || JSON.stringify(err)).substring(0, 300);
const ts = new Date().toLocaleString('en-IN', {timeZone: 'Asia/Kolkata'});
const execId = $execution?.id || 'N/A';
const url = `https://divyesh-sharma.app.n8n.cloud/workflow/298f3JSOE72nhW59/executions/${execId}`;
const text = `?? *EL Node Failed*\n\n? *Node:* \`${nodeName}\`\n?? *Error:* ${msg}\n?? *Time (IST):* ${ts}\n?? [View Execution](${url})`;
return [{json:{text}}];

const PRODUCT_TERMS = [
  'phone case',
  't shirt',
  'hoodie',
  'poster',
  'mug',
  'keychain',
  'action figure',
  'building blocks',
  'toy',
  'plush',
  'figurine',
  'sticker',
  'cover',
  'shirt',
  'case',
  'cap',
];
const MERCH_TERMS = new Set(['t shirt', 'hoodie', 'poster', 'mug', 'keychain', 'sticker', 'shirt', 'case', 'cover', 'cap']);

function compact(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function normalize(value) {
  return compact(value).toLowerCase().replace(/[^a-z0-9\s]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function cleanEntity(raw) {
  let text = compact(raw);
  if (!text) return '';
  text = text.split('|')[0];
  text = text
    .replace(/#\S+/g, ' ')
    .replace(/\b(official|video|song|trailer|teaser|live|lyrics|audio|full|viral|new)\b/ig, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (text.length > 80) text = text.split(' ').slice(0, 8).join(' ');
  return compact(text);
}

function detectProductTerm(query, suggestedType) {
  const hay = normalize([query, suggestedType].filter(Boolean).join(' '));
  for (const term of PRODUCT_TERMS) {
    if (hay.includes(normalize(term))) return term;
  }
  const queryWords = normalize(query).split(' ').filter(Boolean);
  if (queryWords.length >= 2) return queryWords.slice(-2).join(' ');
  if (queryWords.length === 1) return queryWords[0];
  const typeWords = normalize(suggestedType).split(' ').filter(Boolean);
  return typeWords.slice(0, 2).join(' ');
}

function looksMerchTopic(topic, query, productTerm) {
  const text = [topic, query, productTerm].filter(Boolean).join(' ');
  return /(series|movie|trailer|song|music|video|bgmi|minecraft|marvel|wolverine|sidhu|amrit|kalabhavan|teaser)/i.test(text);
}

const items = $input.all();
const out = [];
for (const it of items) {
  const j = it.json || {};
  if (j.error) continue;

  const searchQuery = compact(j.search_query_in || '');
  const entity = cleanEntity(j.topic || searchQuery);
  let productTerm = detectProductTerm(searchQuery, j.suggested_product_type || '');
  const merchIntent = looksMerchTopic(j.topic || '', searchQuery, productTerm);
  if (!productTerm && merchIntent) productTerm = 't shirt';
  let keyword = compact(searchQuery || [entity, productTerm].filter(Boolean).join(' '));
  if (!keyword) keyword = compact(j.topic || '');
  keyword = keyword.slice(0, 120);
  if (!keyword) continue;

  let tavilyQuery = 'buy ' + keyword + ' india';
  if (entity && productTerm) {
    if (merchIntent || MERCH_TERMS.has(productTerm)) {
      tavilyQuery = 'buy "' + entity + '" merchandise ' + productTerm + ' india';
    } else {
      tavilyQuery = 'buy "' + entity + '" ' + productTerm + ' india';
    }
  } else if (searchQuery) {
    tavilyQuery = 'buy ' + searchQuery + ' india';
  }

  out.push({ json: {
    keyword,
    tavily_query: compact(tavilyQuery).slice(0, 180),
    entity_hint: entity || null,
    product_hint: productTerm || null,
    intent_mode: merchIntent || MERCH_TERMS.has(productTerm) ? 'merch' : 'direct_product',
    source_topic: j.topic || keyword,
    source_pick_rank: j.rank ?? null,
    opportunity_score: j.opportunity_score ?? null,
    run_date: j.run_date || new Date().toISOString().substring(0, 10),
    suggested_product_type: j.suggested_product_type || null,
    target_audience: j.target_audience || null,
  }});
}
return out;

const STOP = new Set(['the', 'and', 'for', 'with', 'from', 'that', 'this', 'your', 'into', 'online', 'india', 'buy']);
const MERCH_PRODUCT_TERMS = new Set(['t shirt', 'hoodie', 'poster', 'mug', 'keychain', 'sticker', 'shirt', 'case', 'cover', 'cap']);
const PRODUCT_ALIASES = {
  't shirt': ['t shirt', 'tshirt', 'shirt', 'tee', 'hoodie'],
  'hoodie': ['hoodie', 'sweatshirt'],
  'poster': ['poster', 'wall poster'],
  'mug': ['mug', 'cup'],
  'keychain': ['keychain', 'key chain'],
  'sticker': ['sticker'],
  'phone case': ['phone case', 'case', 'cover'],
  'action figure': ['action figure', 'figurine', 'collectible', 'toy'],
  'building blocks': ['building blocks', 'blocks', 'brick', 'bricks', 'lego'],
};

function compact(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function normalizeText(value) {
  return compact(value).toLowerCase().replace(/[^a-z0-9\s]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function tokenize(value) {
  return normalizeText(value).split(' ').filter(word => word.length > 2 && !STOP.has(word));
}

function urlLooksBad(url) {
  const value = String(url || '').toLowerCase();
  return /[?&](k|q|keyword|search)=/.test(value)
    || /\/s(\?|\/|$)/.test(value)
    || /(showroom|wholesale|collections?|category|categories|browse|results|product-insights|unboxed|blog|blogs|article|articles)/.test(value);
}

function urlLooksProduct(url) {
  const value = String(url || '').toLowerCase();
  return /(\/dp\/|\/gp\/product\/|\/product\/|\/products\/|\/item\/|\/offer\/|\/p\/)/.test(value)
    || /\/b0[a-z0-9]{8,}/.test(value);
}

function overlapCount(text, tokens) {
  return tokens.reduce((count, token) => count + (text.includes(token) ? 1 : 0), 0);
}

function productMatchCount(text, productHint) {
  const aliases = PRODUCT_ALIASES[productHint] || (productHint ? [productHint] : []);
  const normalized = normalizeText(text);
  return aliases.reduce((count, alias) => count + (normalized.includes(normalizeText(alias)) ? 1 : 0), 0);
}

function isBookLike(text) {
  return /\b(book|books|novel|novels|paperback|hardcover|kindle|author|authors)\b/i.test(text);
}

function qualityScore(result, meta) {
  const url = String(result.url || '');
  const title = compact(result.title || '');
  const raw = compact(result.raw_content || result.content || '');
  const text = normalizeText(title + ' ' + raw);
  const productTokens = tokenize(meta.product_hint || meta.keyword || '');
  const entityTokens = tokenize(meta.entity_hint || '');
  const merchIntent = meta.intent_mode === 'merch' || /(merchandise|t shirt|hoodie|poster|mug|keychain|case|shirt|cover|cap)/i.test(meta.tavily_query || meta.keyword || '');
  const productMatches = productMatchCount(title + ' ' + raw, meta.product_hint || '');
  const entityMatches = overlapCount(text, entityTokens);

  let score = Number(result.score || 0) * 10;
  if (urlLooksProduct(url)) score += 4;
  if (/(?:rs\.?|inr|\u20b9)\s*\d/i.test(raw)) score += 2;
  if (/\b\d(?:\.\d)?\s*(?:out of 5|\/5|stars?)\b/i.test(raw)) score += 1.5;
  if (/ratings?|reviews?/i.test(raw)) score += 1.2;
  score += overlapCount(text, productTokens) * 1.8;
  score += entityMatches * 1.4;
  score += productMatches * 2.4;
  if (meta.entity_hint && text.includes(normalizeText(meta.entity_hint))) score += 2;
  if (merchIntent && productMatches === 0) score -= 10;
  if (merchIntent && entityTokens.length && entityMatches === 0) score -= 8;
  if (merchIntent && isBookLike(text)) score -= 12;
  if (!merchIntent && entityTokens.length && entityMatches === 0) score -= 3;
  if (urlLooksBad(url)) score -= 8;
  return score;
}

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i].json || {};
  const meta = $('Build Tavily Query').all()[i]?.json || {};
  const results = Array.isArray(it.results) ? it.results : [];
  const ranked = results
    .filter(result => result && result.url)
    .map(result => {
      const text = (result.title || '') + ' ' + (result.raw_content || result.content || '');
      return {
        ...result,
        _entity_matches: overlapCount(normalizeText(text), tokenize(meta.entity_hint || '')),
        _product_matches: productMatchCount(text, meta.product_hint || ''),
        _is_book_like: isBookLike(text),
        _quality: qualityScore(result, meta),
      };
    })
    .sort((a, b) => (b._quality || 0) - (a._quality || 0));

  const safe = ranked.filter(result =>
    !urlLooksBad(result.url)
    && !result._is_book_like
    && (result._quality || 0) >= 8
    && (
      (meta.intent_mode === 'merch' && result._product_matches > 0 && (!meta.entity_hint || result._entity_matches > 0))
      || (meta.intent_mode !== 'merch' && (result._entity_matches > 0 || result._product_matches > 0))
    )
  );
  const preferred = safe.filter(result => urlLooksProduct(result.url) && (result._quality || 0) >= 11);
  const chosen = [];
  const seen = new Set();

  function pushResult(result, mode) {
    if (!result || !result.url || seen.has(result.url)) return;
    seen.add(result.url);
    const raw = compact(result.raw_content || result.content || '').substring(0, 60000);
    chosen.push({
      json: {
        run_date: meta.run_date ?? null,
        source_topic: meta.source_topic ?? null,
        source_pick_rank: meta.source_pick_rank ?? null,
        opportunity_score: meta.opportunity_score ?? null,
        tavily_query: meta.tavily_query ?? null,
        entity_hint: meta.entity_hint ?? null,
        product_hint: meta.product_hint ?? null,
        intent_mode: meta.intent_mode ?? null,
        tavily_url: result.url,
        tavily_title: result.title || '',
        tavily_score: result.score || 0,
        tavily_quality_score: result._quality || 0,
        tavily_entity_matches: result._entity_matches || 0,
        tavily_product_matches: result._product_matches || 0,
        tavily_raw_content: raw,
        tavily_content_len: raw.length,
        tavily_domain: (() => { try { return new URL(result.url).hostname; } catch { return null; } })(),
        tavily_is_likely_product_page: urlLooksProduct(result.url),
        tavily_selection_mode: mode,
        suggested_product_type: meta.suggested_product_type ?? null,
        target_audience: meta.target_audience ?? null,
      }
    });
  }

  for (const result of preferred) {
    if (chosen.length >= 3) break;
    pushResult(result, 'preferred');
  }
  for (const result of safe) {
    if (chosen.length >= 3) break;
    pushResult(result, 'fallback_safe');
  }
  if (!chosen.length && ranked.length) {
    pushResult(ranked[0], 'last_resort');
  }

  out.push(...chosen);
}
return out;

