function parseFirstJsonObject(text) {
  if (!text) return {};
  try {
    const match = String(text).match(/\{[\s\S]*\}/);
    return match ? JSON.parse(match[0]) : {};
  } catch {
    return {};
  }
}

function compact(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function normalizeText(value) {
  return compact(value).toLowerCase().replace(/[^a-z0-9\s]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function tokenize(value) {
  return normalizeText(value).split(' ').filter(token => token.length > 2);
}

function overlapCount(text, tokens) {
  return tokens.reduce((count, token) => count + (text.includes(token) ? 1 : 0), 0);
}

function toNumber(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const cleaned = compact(value).replace(/,/g, '');
  const match = cleaned.match(/[\d.]+/g);
  if (!match || !match.length) return null;
  const parsed = Number(match[0]);
  return Number.isFinite(parsed) ? parsed : null;
}

function urlLooksBad(url) {
  const value = String(url || '').toLowerCase();
  return /[?&](k|q|keyword|search)=/.test(value)
    || /\/s(\?|\/|$)/.test(value)
    || /(showroom|wholesale|collections?|category|categories|browse|results|product-insights|unboxed|blog|blogs|article|articles)/.test(value);
}

function urlLooksProduct(url) {
  const value = String(url || '').toLowerCase();
  return /(\/dp\/|\/gp\/product\/|\/product\/|\/products\/|\/item\/|\/offer\/|\/p\/)/.test(value)
    || /\/b0[a-z0-9]{8,}/.test(value);
}

function parseImageUrls(value) {
  if (Array.isArray(value)) {
    return value.map(item => compact(item)).filter(item => /^https?:\/\//i.test(item));
  }
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) {
        return parsed.map(item => compact(item)).filter(item => /^https?:\/\//i.test(item));
      }
    } catch {}
    if (/^https?:\/\//i.test(value.trim())) return [value.trim()];
  }
  return [];
}

function detectImageUrls(text) {
  const matches = String(text || '').match(/https?:\/\/[^\s"'()]+(?:jpg|jpeg|png|webp|gif)/ig) || [];
  return [...new Set(matches.map(item => compact(item)).filter(Boolean))].slice(0, 5);
}

function isUsableImageUrl(url) {
  const value = String(url || '').toLowerCase();
  if (!/^https?:\/\//i.test(value)) return false;
  if (/(sprite|logo|icon|flag|placeholder|spacer|privacy|batman-returns|moengage|avatar|profileimage)/.test(value)) return false;
  if (/\.gif(?:\?|$)/.test(value)) return false;
  if (/\/gif(?:\/|\?|$)/.test(value)) return false;
  return true;
}

function detectPriceText(text) {
  const match = String(text || '').match(/(?:^|[\s(])(?:rs\.?|inr|\u20b9)\s*[0-9][0-9,]*(?:\.\d{1,2})?/i);
  return match ? compact(match[0]) : null;
}

function detectRating(text) {
  const match = String(text || '').match(/\b([0-5](?:\.\d)?)\s*(?:out of 5|\/5|stars?)\b/i);
  return match ? toNumber(match[1]) : null;
}

function detectReviewsCount(text) {
  const match = String(text || '').match(/\b([0-9][0-9,]{0,10})\s*(?:ratings?|reviews?)\b/i);
  return match ? Math.round(toNumber(match[1])) : null;
}

function detectAvailability(text) {
  const value = String(text || '').toLowerCase();
  if (/currently unavailable|out of stock|sold out/.test(value)) return 'out_of_stock';
  if (/\bin stock\b/.test(value)) return 'in_stock';
  return 'unknown';
}

function cleanTitle(title) {
  const text = compact(title);
  if (!text) return null;
  const cleaned = text
    .replace(/^amazon\.in\s*:\s*/i, '')
    .replace(/^buy\s+/i, '')
    .replace(/\s+online at low prices in india.*$/i, '')
    .replace(/\s+\|\s+amazon\.in.*$/i, '')
    .replace(/\s+:\s+amazon\.in.*$/i, '')
    .replace(/\s+-\s+amazon\.in.*$/i, '')
    .replace(/\s+-\s+alibaba\.com.*$/i, '')
    .trim();
  if (!cleaned || /^404\b/i.test(cleaned)) return null;
  return cleaned;
}

function productMatchCount(text, productHint) {
  const aliases = {
    't shirt': ['t shirt', 'tshirt', 'shirt', 'tee', 'hoodie'],
    'hoodie': ['hoodie', 'sweatshirt'],
    'poster': ['poster', 'wall poster'],
    'mug': ['mug', 'cup'],
    'keychain': ['keychain', 'key chain'],
    'sticker': ['sticker'],
    'phone case': ['phone case', 'case', 'cover'],
    'action figure': ['action figure', 'figurine', 'collectible', 'toy'],
    'building blocks': ['building blocks', 'blocks', 'brick', 'bricks', 'lego'],
  };
  const list = aliases[productHint] || (productHint ? [productHint] : []);
  const normalized = normalizeText(text);
  return list.reduce((count, alias) => count + (normalized.includes(normalizeText(alias)) ? 1 : 0), 0);
}

function isBookLike(text) {
  return /\b(book|books|novel|novels|paperback|hardcover|kindle|author|authors)\b/i.test(text);
}

